// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker, address rewardToken, uint256 amount) public {
        vm.assume(staker != address(0) && rewardToken != address(0) && amount < 1e30);
        vm.assume(amount > 0);
        // First, add a reward token
        c.addReward(rewardToken);
        // The claimableRewards for staker and this token should be zero after addReward
        uint256 claimableBefore = c.claimableRewards(staker, rewardToken);

        // Now stake some tokens for staker to earn rewards
        // We need to simulate a reward distribution; call notifyRewardAmount
        // But we need the reward token to have balance; we'll use a mock
        // For simplicity, we revert if claimableRewards is not zero
        assertTrue(claimableBefore == 0, "claimableRewards should be zero after addReward");

        // Now test that when _getReward is called with zero amount, it does not transfer
        // We can trigger getReward through the public interface
        // We'll check the balance of rewardToken before and after
        // But we need a real token; we can use address(this) as a token
        // We'll transfer some tokens to c and then call getReward
        // To make claimableRewards non-zero, we need to stake and notify reward
        // But we just want to test the invariant that after addReward, claimableRewards is zero
        // So we can also test that after calling getReward with zero claimable, nothing happens
        uint256 balBefore = address(this).balance;
        c.getReward(staker, rewardToken);
        // Since claimableRewards was zero, no transfer should occur
        // We check by ensuring the balance hasn't changed (no transfer)
        // For a real test, we'd need to mint tokens; but the invariant is just about claimableRewards
        // So we assert the claimableRewards is still zero
        uint256 claimableAfter = c.claimableRewards(staker, rewardToken);
        assertTrue(claimableAfter == 0, "claimableRewards should remain zero after getReward with zero amount");
    }
}

